<?php pl_ui_page_header('Cash forecast','A simple cash scenario for '.$company['name'].'.',static function (): void { ?><span class="badge badge-info">Planning scenario · Not actuals</span><a class="btn btn-ghost" href="<?= pl_e(pl_url('/reports')) ?>">All reports</a><?php }); ?>
<?php if ($form['message']): ?><div class="alert alert-danger" role="alert" data-form-error><?= pl_e($form['message']) ?> Your assumptions remain below.</div><?php endif; ?>
<div class="grid grid-cols-1 gap-4 lg:grid-cols-[320px_minmax(0,1fr)]"><form method="post" action="<?= pl_e(pl_url('/reports/cash-forecast')) ?>" class="rounded-panel border border-border bg-surface p-4 flex flex-col gap-3"><?= pl_csrf_field() ?><?= pl_scope_fields($company) ?><p class="eyebrow">Your assumptions</p><h2 class="section-title">What might change?</h2><p class="text-xs text-ink-muted">Starting cash is <?= pl_e($company['currency'] . ' ' . pl_money($opening)) ?> from posted cash/bank accounts through <?= pl_e(pl_date_label($asOf)) ?>.</p><div class="flex flex-col gap-3"><label class="field">Expected money in each week<input class="input" type="text" inputmode="decimal" name="weekly_in" value="<?= pl_e($input['weekly_in']) ?>" required pattern="[0-9]+(\.[0-9]{1,4})?"></label><label class="field">Expected money out each week<input class="input" type="text" inputmode="decimal" name="weekly_out" value="<?= pl_e($input['weekly_out']) ?>" required pattern="[0-9]+(\.[0-9]{1,4})?"></label><label class="field">Number of weeks<input class="input" type="number" name="weeks" min="1" max="52" value="<?= pl_e($input['weeks']) ?>" required></label></div><button type="submit" class="btn btn-primary justify-center">Update scenario</button><p class="text-xs text-ink-muted">Use decimal points without separators. <?= $company['is_sample'] ? 'The starting assumptions are illustrative sample amounts.' : 'Enter your own assumptions; no automatic prediction is made.' ?> This does not post entries or change the books.</p></form>
<div><?php if ($forecast): ?><div class="rounded-panel border border-border bg-surface p-4 mb-3"><p class="eyebrow">After <?= (int) $forecast['weeks'] ?> weeks</p><h2><?= pl_e($company['currency'] . ' ' . pl_money($forecast['closing'])) ?></h2><p><?= $forecast['first_negative_week'] !== null ? 'This scenario first falls below zero in week ' . (int) $forecast['first_negative_week'] . '.' : 'Cash stays at or above zero under these assumptions.' ?></p></div><div class="rounded-panel border border-border bg-surface p-4 mb-3"><canvas hidden class="w-full h-auto" width="760" height="280" data-forecast-chart data-values="<?= pl_e(json_encode(array_merge([$forecast['opening']], array_column($forecast['rows'], 'closing')), JSON_THROW_ON_ERROR)) ?>" aria-label="Scenario cash balance by week. Exact amounts appear in the table below." role="img"></canvas><noscript><p class="text-xs text-ink-muted">The exact week-by-week scenario is available in the table below.</p></noscript></div><p class="text-xs text-ink-muted">Opening cash + assumed inflows − assumed outflows. No receivables timing, seasonality, taxes or unrecorded commitments are automatically included.</p><?php else: ?><div class="empty-state"><h2>Adjust the assumptions to continue.</h2><p>The scenario will appear here when the values are valid.</p></div><?php endif; ?></div></div>
<?php if ($forecast): ?><details class="rounded-panel border border-border bg-surface p-4" open><summary>Week-by-week cash plan</summary><div class="table-wrap"><table class="table"><caption class="sr-only">Scenario amounts in <?= pl_e($company['currency']) ?></caption><thead><tr><th>Week</th><th class="amount">Opening</th><th class="amount">Money in</th><th class="amount">Money out</th><th class="amount">Closing</th></tr></thead><tbody><?php foreach ($forecast['rows'] as $row): ?><tr><th scope="row"><?= (int) $row['week'] ?></th><td class="amount"><?= pl_e(pl_money($row['opening'])) ?></td><td class="amount"><?= pl_e(pl_money($row['inflow'])) ?></td><td class="amount"><?= pl_e(pl_money($row['outflow'])) ?></td><td class="amount"><strong><?= pl_e(pl_money($row['closing'])) ?></strong></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?></div>
